import API_CONFIG from "../config.js";
import {validateGeoScenario} from "./jarvis-geospatial-model.js?v=4.96.0";
import {collectGlobalIntelligence} from "../backend/global-intelligence-monitor.js?v=5.12.0";

// Global Intelligence uses the SAME Ring geospatial module and existing globe.
// Source facts are never generated by an LLM or inferred from a dashboard color.
const stage=document.querySelector(".jarvis-cc-center");
const BACKEND=String(API_CONFIG.backendUrl||"").replace(/\/+$/,"");
const SCENARIO="global-intelligence-events-v1";
const kindMap={earthquake:"earthquake",wildfires:"wildfires",volcanoes:"volcanoes",
 severeStorms:"severeStorms",floods:"floods",landslides:"landslides"};
const kindLabel={earthquake:"Sismo",wildfires:"Incêndio",volcanoes:"Vulcão",
 severeStorms:"Tempestade",floods:"Inundação",landslides:"Deslizamento"};
const validUrl=s=>{
 try{
  const u=new URL(String(s||""));
  return u.protocol==="https:"&&[
   "earthquake.usgs.gov","eonet.gsfc.nasa.gov","gdacs.org","www.gdacs.org"
  ].some(host=>u.hostname===host)?u.href:null;
 }catch{return null;}
};
const time=value=>{
 const t=Date.parse(value||"");if(!Number.isFinite(t))return "sem horário";
 return new Intl.DateTimeFormat("pt-BR",{timeZone:"America/Recife",
  day:"2-digit",month:"2-digit",hour:"2-digit",minute:"2-digit"}).format(t);
};
const clean=(value,max=160)=>String(value??"").replace(/[<>\r\n]/g," ").trim().slice(0,max);
const elt=(tag,cls,txt)=>{
 const node=document.createElement(tag);if(cls)node.className=cls;if(txt!==undefined)node.textContent=txt;
 return node;
};
export function verifiedIntelligenceEvents(report){
 if(!report?.ok||!Array.isArray(report.events)||!Array.isArray(report.sourceStatus))return [];
 return report.events.filter(e=>e&&typeof e.id==="string"&&typeof e.source==="string"&&
   Object.hasOwn(kindMap,e.kind)&&typeof e.title==="string"&&
   Number.isFinite(e.lat)&&Number.isFinite(e.lng)&&Math.abs(e.lat)<=90&&Math.abs(e.lng)<=180&&
   validUrl(e.url)&&Number.isFinite(Date.parse(e.eventAt))).slice(0,110);
}
export function intelligenceScenario(report,{scope="world",kind="all"}={}){
 const eligible=verifiedIntelligenceEvents(report).filter(e=>(scope==="world"||e.nearBrazil===true)&&
   (kind==="all"||e.kind===kind));
 if(!eligible.length)return null;
 const sourceCount=report.sourceStatus.filter(s=>s.ok).length;
 const points=eligible.slice(0,20).map(e=>({id:clean(e.id,65),name:clean(e.title,100),lat:e.lat,lng:e.lng,
   kind:kindMap[e.kind],detail:clean(e.description,250)+
     " · Evento: "+time(e.eventAt)+(e.representative?" · ponto representativo":""),
   source:validUrl(e.url),observedAt:e.eventAt}));
 const data={id:SCENARIO,title:"INTELIGÊNCIA GLOBAL · eventos publicados",
  projection:"world",source:{
   name:"USGS / NASA EONET / GDACS ("+sourceCount+"/3 fontes)",
   url:"https://eonet.gsfc.nasa.gov/",
   basePeriod:"Última coleta "+time(report.checkedAt),
   disclaimer:"Eventos reais publicados nas fontes; atualização e cobertura variam. Pinos são localização informada ou aproximada. Prioridade na lista não é gravidade calculada."
  },frames:[{id:"source-events",name:"Eventos confirmados",kind:"observed",
     type:"registros publicados",description:"Informações registradas por fontes, não previsão de desastres.",points}]};
 return validateGeoScenario(data);
}
if(stage){
 const panel=elt("section","jarvis-global-intel-panel");
 panel.hidden=true;panel.setAttribute("aria-label","Inteligência global e monitoramento no Neural Ring");
 const heading=elt("header","jarvis-global-intel-head");
 const title=elt("strong","", "GLOBAL INTELLIGENCE");
 const dismiss=elt("button","","×");dismiss.type="button";dismiss.dataset.intelAction="close";
 dismiss.setAttribute("aria-label","Fechar inteligência global");
 heading.append(title,dismiss);
 const actions=elt("nav","jarvis-global-intel-actions");
 const scopeSelect=elt("select");scopeSelect.setAttribute("aria-label","Região dos eventos");
 for(const [value,label] of [["world","Mundo"],["brazil","Brasil · proximidade"]]){
  const o=elt("option","",label);o.value=value;scopeSelect.append(o);
 }
 const kindSelect=elt("select");kindSelect.setAttribute("aria-label","Tipo do evento");
 for(const [value,label] of [["all","Todos os tipos"],...Object.entries(kindLabel)]){
  const o=elt("option","",label);o.value=value;kindSelect.append(o);
 }
 const mode2d=elt("button","","2D"),mode3d=elt("button","","Globo 3D"),
 refreshButton=elt("button","","Atualizar");
 mode2d.dataset.intelAction="2d";
 mode3d.dataset.intelAction="3d";
 refreshButton.dataset.intelAction="refresh";
 for(const b of [mode2d,mode3d,refreshButton])b.type="button";
 actions.append(scopeSelect,kindSelect,mode2d,mode3d,refreshButton);
 const status=elt("p","jarvis-global-intel-status","Aguardando consulta de fontes.");
 const feed=elt("div","jarvis-global-intel-list");
 const footer=elt("div","jarvis-global-intel-footer");
 panel.append(heading,actions,status,feed,footer);stage.append(panel);
 const wake=elt("div","jarvis-global-intel-wake");wake.hidden=true;
 const wakeButton=elt("button","","INTELIGÊNCIA GLOBAL");wakeButton.type="button";
 wakeButton.dataset.intelAction="wake";
 const wakeText=elt("span","","Aguardando monitoramento mundial");
 const continuityText=elt("span","jarvis-global-continuity","CONTINUIDADE · AGUARDANDO D1");
 const priorityArea=elt("section","jarvis-global-priority");
 priorityArea.setAttribute("aria-label","Prioridades de fontes verificadas");
 const priorityHeading=elt("strong","jarvis-global-priority-heading","PRIORIDADES · AGUARDANDO FONTES");
 const priorityItems=elt("div","jarvis-global-priority-items");
 priorityArea.append(priorityHeading,priorityItems);
 wake.append(wakeButton,wakeText,priorityArea,continuityText);stage.append(wake);
 for(const name of ["pointerdown","pointerup","wheel","click","touchstart","touchend"]){
  panel.addEventListener(name,event=>event.stopPropagation(),{passive:true});
  wake.addEventListener(name,event=>event.stopPropagation(),{passive:true});
 }
 let report=null,fetchAt=0,visible=false,view="2d",scope="world",kind="all",requestId=0;
 let lastFetchMode="unknown",lastError="",inflight=null;
 let lastWakeAt=0,awakened=false;
 const close=()=>{
  ++requestId;visible=false;panel.hidden=true;panel.setAttribute("aria-busy","false");
  if(window.ULTRON_GEO_VISUAL?.state?.scenario===SCENARIO){
   window.ULTRON_GEO_VISUAL?.close?.();
   window.ULTRON_EARTH?.close?.();
  }
  return {ok:true,visible:false};
 };
 const sourcePanel=()=>{
  footer.replaceChildren();
  for(const s of report?.sourceStatus||[]){
   const item=elt("span","",s.source.toUpperCase()+": "+(s.ok?"consultada":"indisponível"));
   item.className="jarvis-global-source"+(s.ok?"":" missing");footer.append(item);
  }
 };
 async function getReport(force=false){
  if(!force&&report&&Date.now()-fetchAt<4*60000)return report;
  // Several buttons may request one update at the same time; share the fetch.
  if(inflight)return inflight;
  inflight=(async()=>{
    let backendError="Backend indisponível";
    if(BACKEND){
      const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),8000);
      try{
        const res=await fetch(BACKEND+"/api/intelligence/global",{
          headers:{Accept:"application/json"},signal:ctl.signal,cache:"no-store"});
        const data=await res.json().catch(()=>null);
        if(!res.ok||!data?.ok||!Array.isArray(data.sourceStatus))
          throw Error(data?.error||"HTTP "+res.status);
        report=data;fetchAt=Date.now();
        lastFetchMode=data.persistence==="direct-live-fallback"?"worker-live":"d1";
        lastError="";return data;
      }catch(error){backendError=clean(error?.message||error,130);}
      finally{clearTimeout(timer);}
    }
    // Cloudflare routes can lag behind GitHub Pages or D1 may be empty.
    // Query genuine public GeoJSON feeds DIRECTLY inside this Ring; do not
    // open external webpages and do not call these values a D1 monitoring history.
    status.textContent="Backend sem dados ("+backendError+"). "+
      "Consultando fontes públicas diretamente no Neural Ring…";
    const live=await collectGlobalIntelligence();
    if(!live.ok||!Array.isArray(live.sourceStatus))
      throw Error("Cloudflare: "+backendError+
        ". Fontes diretas: "+clean(live.error||"indisponíveis",120)+
        ". Sem eventos fictícios.");
    report={...live,persistence:"browser-direct",
      stale:false,ageMinutes:0,cadenceHours:null};
    fetchAt=Date.now();lastFetchMode="browser-direct";
    lastError=backendError;
    return report;
  })();
  try{return await inflight;}
  finally{inflight=null;}
 }
 function renderList(selected,request){
  feed.replaceChildren();
  for(const item of selected.slice(0,14)){
   const article=elt("article","jarvis-global-intel-item");
   const button=elt("button","jarvis-global-intel-event",clean(item.title,120));
   button.dataset.intelAction="focus";
   button.type="button";button.setAttribute("title","Centralizar evento no globo");
   const meta=elt("small","",String(kindLabel[item.kind]||item.kind)+
     " · "+item.source.toUpperCase()+" · "+time(item.eventAt)+
     (item.gdacsAlert?" · GDACS "+item.gdacsAlert.toUpperCase():""));
   const link=elt("a","","Fonte verificada");
   link.href=validUrl(item.url);link.target="_blank";link.rel="noopener noreferrer";
   button.addEventListener("click",async()=>{
     if(request!==requestId||!visible)return;
     status.textContent="Localizando "+clean(item.title,95)+" no globo…";
     const earth=window.ULTRON_EARTH;
     if(window.ULTRON_GEO_VISUAL?.state?.mode!=="3d"){
       const changed=await window.ULTRON_GEO_VISUAL?.setMode?.("3d");
       if(!changed?.ok){status.textContent="Globo indisponível: "+clean(changed?.error,100);return;}
       view="3d";
     }
     const focusResult=earth?.focus?.(item.lat,item.lng,5,false,item.title);
     if(!focusResult?.ok){
       status.textContent="Não foi possível centralizar o globo: "+
         clean(focusResult?.error||"motor geográfico indisponível",130);return;
     }
     status.textContent="Localização selecionada: "+clean(item.title,110)+
       " · "+time(item.eventAt)+". Fonte: "+item.source.toUpperCase()+
       ". Posição representativa pode não ser o centro real da área afetada.";
   });
   article.append(button,meta,link);feed.append(article);
  }
 }
 async function draw(request){
  if(request!==requestId||!visible)return {ok:false,error:"Visualização cancelada"};
  const selected=verifiedIntelligenceEvents(report).filter(e=>
    (scope==="world"||e.nearBrazil===true)&&(kind==="all"||e.kind===kind));
  const available=report.sourceStatus.filter(s=>s.ok).length;
  const age=Date.now()-Date.parse(report.checkedAt);
  status.textContent="COLETA "+time(report.checkedAt)+" · "+available+"/3 fontes · "+
   selected.length+" registros no filtro · "+(report.stale||age>2*3600000?
   "DADOS DEFASADOS · ":"")+
   (report.partial?"Cobertura parcial. ":"")+
   (scope==="brazil"?"Brasil: área retangular aproximada, não fronteira oficial. ":"")+
   "Eventos publicados, não risco previsto."+
   (report.persistence==="browser-direct"?
     " · Dados consultados diretamente (sem histórico D1).":
     report.persistence==="direct-live-fallback"?
     " · Consulta sob demanda do Worker (sem histórico D1).":"");
  sourcePanel();renderList(selected,request);
  if(!selected.length){
   window.ULTRON_GEO_VISUAL?.close?.();
   feed.append(elt("p","jarvis-global-intel-empty",
     "Nenhum evento disponível neste filtro nas fontes consultadas. Isso NÃO significa ausência de riscos."));
   return {ok:true,visible:true,eventCount:0,noEvents:true};
  }
  const data=intelligenceScenario(report,{scope,kind});
  if(!data){
    status.textContent="As fontes responderam, mas não foi possível validar os pontos do mapa. "+
      "Confira horários, origem e formato das coordenadas.";
    return {ok:false,error:"Não foi possível validar dados geográficos"};
  }
  if(!window.ULTRON_GEO_VISUAL)await import("./jarvis-geospatial-visual.js?v=4.96.0");
  const result=await window.ULTRON_GEO_VISUAL.open({data,view});
  if(request!==requestId||!visible)return {ok:false,error:"Visualização substituída"};
  if((!result?.ok||window.ULTRON_GEO_VISUAL.state.scenario!==SCENARIO)&&view==="3d"){
    // Do not leave a dead 3D button when Mapbox/WebGL cannot initialize.
    view="2d";mode2d.setAttribute("aria-pressed","true");
    mode3d.setAttribute("aria-pressed","false");
    status.textContent+=" Globo 3D indisponível: "+
      clean(result?.error||"WebGL/Mapbox falhou",100)+". Tentando o mapa 2D no Ring.";
    const fallback=await window.ULTRON_GEO_VISUAL.open({data,view:"2d"});
    if(request===requestId&&visible&&fallback?.ok)
      return {ok:true,visible:true,eventCount:selected.length,
        plotted:Math.min(20,selected.length),view:"2d",
        fallback3d:true,checkedAt:report.checkedAt,partial:report.partial};
  }
  if(!result?.ok||window.ULTRON_GEO_VISUAL.state.scenario!==SCENARIO){
   status.textContent+=" Não foi possível confirmar o mapa: "+clean(result?.error,120);
   return {ok:false,error:"Falha ao abrir mapa dentro do Ring"};
  }
  return {ok:true,visible:true,eventCount:selected.length,plotted:Math.min(20,selected.length),
    view,checkedAt:report.checkedAt,partial:report.partial};
 }
 async function open({view:mode="2d",region="world",category="all",refresh=false}={}){
  ++requestId;const request=requestId;
  view=mode==="3d"?"3d":"2d";
  scope=region==="brazil"?"brazil":"world";
  kind=Object.hasOwn(kindMap,category)?category:"all";
  scopeSelect.value=scope;kindSelect.value=kind;
  visible=true;panel.hidden=false;wake.hidden=true;
  panel.setAttribute("aria-busy","true");
  mode2d.setAttribute("aria-pressed",String(view==="2d"));
  mode3d.setAttribute("aria-pressed",String(view==="3d"));
  refreshButton.setAttribute("aria-label","Atualizar fontes globais");
  window.ULTRON_METEO_CENTER?.close?.();
  window.ULTRON_NEURAL_ANSWER?.clear?.();
  status.textContent="Conectando à coleta mundial persistida no Cloudflare D1…";
  try{
   await getReport(refresh);
   if(request!==requestId||!visible)return {ok:false,error:"Consulta substituída"};
   const drawn=await draw(request);
   return drawn;
  }catch(error){
   if(request===requestId&&visible){
    feed.replaceChildren();footer.replaceChildren();
    status.textContent="GLOBAL INTELLIGENCE INDISPONÍVEL · "+
     clean(error?.message,160)+". Nenhum evento fictício será exibido.";
   }
   return {ok:false,visible,error:clean(error?.message,140)};
  }finally{
   if(request===requestId)panel.setAttribute("aria-busy","false");
  }
 }
 const redraw=()=>void open({view,region:scopeSelect.value,category:kindSelect.value});
 mode2d.addEventListener("click",()=>void open({view:"2d",region:scope,category:kind}));
 mode3d.addEventListener("click",()=>void open({view:"3d",region:scope,category:kind}));
 refreshButton.addEventListener("click",()=>void open({view,region:scope,category:kind,refresh:true}));
 scopeSelect.addEventListener("change",redraw);
 kindSelect.addEventListener("change",redraw);
 dismiss.addEventListener("click",close);
 wakeButton.addEventListener("click",()=>void open({view:"3d"}));
 const quick=document.querySelector(".quick-actions");
 if(quick&&!document.getElementById("btn-global-intelligence")){
  const btn=elt("button","","GLOBAL INTEL");btn.id="btn-global-intelligence";btn.type="button";
  btn.dataset.intelAction="open";
  // A pointerdown may cause the Ring to change visual layout before click
  // is dispatched. Act on pointerdown like the existing quick Earth button,
  // while retaining keyboard accessibility through click.
  let pointerOpenAt=0;
  btn.addEventListener("pointerdown",event=>{
    if(event.button!==0)return;
    pointerOpenAt=Date.now();
    void open({view:"3d"});
  });
  btn.addEventListener("click",()=>{
    if(Date.now()-pointerOpenAt<800)return;
    void open({view:"3d"});
  });
  // World monitoring and radar are priority actions on narrow screens.
  quick.prepend(btn);
  const radar=document.getElementById("btn-meteo-center");
  if(radar&&quick.contains(radar))btn.after(radar);
 }
 // Existing wake state already triggers a separate spoken news briefing.
 // Add nonintrusive sourced event status; DO NOT interrupt its narration.
 window.addEventListener("ultron:wake-state",event=>{
  const awake=Boolean(event?.detail?.awake);
  if(awake&&!awakened&&Date.now()-lastWakeAt>12000){
   lastWakeAt=Date.now();
   void getReport().then(data=>{
    if(!data?.ok||visible)return;
    const sources=data.sourceStatus.filter(s=>s.ok).length;
    const events=verifiedIntelligenceEvents(data);
    const age=Date.now()-Date.parse(data.checkedAt);
    wakeText.textContent="Global: "+events.length+" eventos publicados · "+
      sources+"/3 fontes · "+time(data.checkedAt)+
      (data.stale||age>2*3600000?" · dados defasados":"");
    wake.hidden=false;
    window.dispatchEvent(new CustomEvent("ultron:global-intelligence-update",{detail:{
      sourceCount:sources,eventCount:events.length,checkedAt:data.checkedAt,stale:data.stale||age>2*3600000
    }}));
   }).catch(()=>{wakeText.textContent="Inteligência global sem coleta confirmada";
     wake.hidden=false;});
  }
  awakened=awake;
 });
 // Continuity only displays validated D1 collection age and provider health.
 // Never reinterpret a sample as an alert or predicted event.
 window.addEventListener("ultron:continuity-report",event=>{
  const detail=event?.detail||{};
  continuityText.textContent=clean(detail.ring||
    "CONTINUIDADE · INDISPONÍVEL",130);
  if(detail.waking===true)wake.hidden=false;
 });
 window.addEventListener("ultron:contextual-priorities",event=>{
  const detail=event?.detail||{};
  if(detail.ok!==true)return;
  const items=Array.isArray(detail.items)?detail.items.slice(0,3):[];
  priorityHeading.textContent="PRIORIDADES VERIFICADAS · "+items.length+
    " destaque(s) · "+Math.max(0,Number(detail.newCount)||0)+" novos no resumo";
  priorityItems.replaceChildren();
  if(!items.length){
   priorityItems.append(elt("p","jarvis-global-priority-empty",
    "Sem destaques atuais confirmados nas fontes disponíveis."));
  }
  for(const item of items){
   const row=elt("div","jarvis-global-priority-entry");
   const source=clean(item.verifiedLabel||item.source||"Fonte",95);
   const meta=elt("small","",source+" · "+clean(item.region||"",65)+
     (item.isNew?" · NOVO NO RESUMO":""));
   const url=validUrl(item.url);
   const headline=elt(url?"a":"span","",clean(item.title||"Sem título",135));
   if(url){headline.href=url;headline.target="_blank";headline.rel="noopener noreferrer";}
   row.append(meta,headline);
   priorityItems.append(row);
  }
  if(detail.waking===true||detail.manual===true)wake.hidden=false;
 });
 window.addEventListener("ultron:new-conversation",close);
 window.ULTRON_GLOBAL_INTELLIGENCE={open,close,refresh:()=>open({view,region:scope,category:kind,refresh:true}),
  get state(){return {visible,view,region:scope,category:kind,hasReport:!!report,
   lastFetchMode,lastError,loading:!!inflight,
   checkedAt:report?.checkedAt||null,stale:report?.stale??true,
   sources:report?.sourceStatus?.filter(x=>x.ok).length||0,
   count:report?.eventCount||0};}};
}
